<style>.cp{display:grid;gap:16px}.cp-card{border:1px solid rgba(128,128,128,.2);border-radius:14px;background:rgba(128,128,128,.04);overflow:hidden}.cp-pad{padding:14px}.cp-form{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cp label{display:block;font-size:12px;font-weight:700;opacity:.6;margin-bottom:4px}.cp input,.cp select,.cp textarea{width:100%;border:1px solid rgba(128,128,128,.3);border-radius:9px;padding:8px;background:transparent}.cp button{border:0;border-radius:9px;padding:9px 14px;background:#2563eb;color:white;font-weight:700;cursor:pointer}.cp-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:10px}.cp-plan{padding:14px;cursor:pointer}.cp-plan:hover{background:rgba(37,99,235,.05)}.cp-title{font-weight:800}.cp-meta{font-size:12px;opacity:.65;margin-top:4px}.cp-badge{display:inline-block;font-size:11px;padding:2px 7px;border-radius:999px;background:rgba(128,128,128,.12)}.cp-topic{display:grid;grid-template-columns:45px 1fr 90px 130px;gap:10px;padding:10px 14px;border-top:1px solid rgba(128,128,128,.12);align-items:center}.cp-topic b{color:#2563eb}.cp-section{padding:10px 14px;font-weight:800;border-bottom:1px solid rgba(128,128,128,.15)}@media(max-width:750px){.cp-form{grid-template-columns:1fr}.cp-topic{grid-template-columns:35px 1fr}.cp-topic>*:nth-child(n+3){grid-column:2}.cp-list{grid-template-columns:1fr}}</style>
